package com.rezoxnemesis.videostudio;
import ai.onnxruntime.*;
import ai.onnxruntime.platform.Fp16Conversions;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

/** Real old4-token -> repeated16-token CPU equivalence. No artwork or likeness assertion. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class LocalDrawingPlusLegacyEquivalenceStudyTest {
 // Budgets predeclared before executing either model; never inferred from measured errors.
 private static final double MAX_ABS_BUDGET=.02,RMS_BUDGET=.003;
 private static final int[] INNER={320,320,640,640,1280,1280,1280,1280,1280,640,640,640,320,320,320,1280};
 private static final long[][] RESIDUALS={{1,320,64,64},{1,320,64,64},{1,320,64,64},{1,320,32,32},{1,640,32,32},{1,640,32,32},{1,640,16,16},{1,1280,16,16},{1,1280,16,16},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8}};
 private OrtEnvironment environment;
 @Test public void originalNoiseMatchesRepeatedRealFourTokenKvWithinPredeclaredFp16Budget()throws Exception {
  String path=System.getenv("VIDEOSTUDIO_PLUS_LEGACY_EQUIVALENCE");Assume.assumeTrue("Explicit actual legacy-equivalence study",path!=null&&!path.isEmpty());JSONObject config=new JSONObject(new String(Files.readAllBytes(new File(path).toPath()),StandardCharsets.UTF_8));File directory=new File(config.getString("outputDirectory"));assertTrue(directory.mkdirs()||directory.isDirectory());File evidence=new File(directory,"native-legacy-equivalence.json");assertFalse("Preserve previous trials",evidence.exists());JSONObject report=new JSONObject().put("status","RUNNING").put("sourceCommit",config.getString("sourceCommit")).put("sourceState",config.getString("sourceState")).put("maxAbsBudget",MAX_ABS_BUDGET).put("rmsBudget",RMS_BUDGET).put("budgetsDeclaredBeforeExecution",true).put("oldNewSessionsSequential",true).put("appVersion",AppProtocol.APP_VERSION).put("phoneExecution",false).put("inferenceExecuted",false).put("artworkProduced",false).put("creativeScenarios",0).put("pixelIdentityClaimed",false).put("startedAt",System.currentTimeMillis());write(evidence,report);
  try(LocalDrawingEngine runner=new LocalDrawingEngine()){
   environment=OrtEnvironment.getEnvironment();File audit=new File(config.getString("auditUnet")),converted=new File(config.getString("convertedUnet")),control=new File(config.getString("controlnet"));String auditSha=config.getString("auditSha256");assertTrue(auditSha.matches("[a-f0-9]{64}")&&!auditSha.equals("0".repeat(64)));assertEquals(auditSha,LocalDrawingModels.hash(audit));assertEquals("d53c027c7a0ea50f737fe57a2f68ab5f980b0c6199c4980cb96ff66de5da00f6",LocalDrawingModels.hash(converted));assertEquals("399358929322eb5bb2f0e141e23486397a29ec871e4efa625c0f2ba4d418c698",LocalDrawingModels.hash(control));JSONObject verified=new JSONObject(new String(Files.readAllBytes(new File(config.getString("auditVerificationEvidence")).toPath()),StandardCharsets.UTF_8));assertEquals("TECHNICAL_CONVERSION_PASS_RUNTIME_UNVERIFIED",verified.getString("status"));assertEquals(auditSha,verified.getJSONArray("models").getJSONObject(0).getString("verifiedDerivedSha256"));assertEquals("sd15_legacy_ipkv_probe_v1",verified.getJSONArray("models").getJSONObject(0).getString("recipe"));
   float[] latents=new float[4*64*64],text=new float[77*768],pooled=new float[1024];for(int i=0;i<latents.length;i++)latents[i]=(float)(.15*Math.sin(i*.013));for(int i=0;i<text.length;i++)text[i]=(float)(.05*Math.cos(i*.007));for(int i=0;i<pooled.length;i++)pooled[i]=(float)(.25*Math.cos(i*.019));float[][] residuals;
   try(OrtSession session=runner.open(control.getParentFile(),control.getName())){report.put("controlOutputs",metadata(session.getOutputInfo()));residuals=control(runner,session,latents,text);}report.put("inferenceExecuted",true);float[] originalNoise;float[][] originalKv=new float[32][];
   try(OrtSession session=runner.open(audit.getParentFile(),audit.getName())){
    assertEquals(17,session.getInputInfo().size());assertEquals(33,session.getOutputInfo().size());report.put("oldInputs",metadata(session.getInputInfo())).put("oldOutputs",metadata(session.getOutputInfo()));Map<String,OnnxTensor> inputs=new LinkedHashMap<>();List<OnnxTensor> owned=new ArrayList<>();try{base(inputs,owned,latents,text,residuals);put(inputs,owned,"image_embeds",half(pooled,1,1,1024));try(OrtSession.Result result=runner.run(session,inputs)){originalNoise=values(result,"noise_pred",1,4,64,64);for(int i=0;i<16;i++){originalKv[i]=values(result,LocalDrawingPlusLegacyAuditGraphTest.output(i,true),1,1,4,INNER[i]);originalKv[16+i]=values(result,LocalDrawingPlusLegacyAuditGraphTest.output(i,false),1,1,4,INNER[i]);}}}finally{for(OnnxTensor tensor:owned)tensor.close();}
   }
   report.put("oldSessionClosedBeforeNew",true);write(evidence,report);float[] repeatedNoise;
   try(OrtSession session=runner.open(converted.getParentFile(),converted.getName())){
    assertEquals(48,session.getInputInfo().size());report.put("newInputs",metadata(session.getInputInfo())).put("newOutputs",metadata(session.getOutputInfo()));Map<String,OnnxTensor> inputs=new LinkedHashMap<>();List<OnnxTensor> owned=new ArrayList<>();try{base(inputs,owned,latents,text,residuals);for(int i=0;i<16;i++){float[] key=new float[INNER[i]*16],value=new float[INNER[i]*16];for(int token=0;token<16;token++)for(int channel=0;channel<INNER[i];channel++){key[channel*16+token]=originalKv[i][(token/4)*INNER[i]+channel];value[token*INNER[i]+channel]=originalKv[16+i][(token/4)*INNER[i]+channel];}put(inputs,owned,"ipk_"+i,half(key,1,INNER[i],16));put(inputs,owned,"ipv_"+i,half(value,1,16,INNER[i]));}try(OrtSession.Result result=runner.run(session,inputs)){repeatedNoise=values(result,"noise_pred",1,4,64,64);}}finally{for(OnnxTensor tensor:owned)tensor.close();}
   }
   JSONObject delta=difference(originalNoise,repeatedNoise);report.put("delta",delta).put("originalNoise",tensorFile(directory,"original-noise.f32",originalNoise)).put("convertedNoise",tensorFile(directory,"repeated16-noise.f32",repeatedNoise)).put("unetForwardPasses",2).put("controlForwardPasses",1).put("repeatRule","Each actual old token is duplicated4times; K also transposes to channel-first");write(evidence,report);assertTrue(delta.toString(),delta.getDouble("maxAbs")<=MAX_ABS_BUDGET);assertTrue(delta.toString(),delta.getDouble("rms")<=RMS_BUDGET);report.put("status","TECHNICAL_FP16_BUDGET_PASS_NOT_PIXEL_IDENTITY").put("runtimeVersion",runner.runtimeVersion());
  }catch(Exception|AssertionError|LinkageError failure){report.put("status","FAIL").put("error",failure.toString());throw failure;}
  finally{report.put("finishedAt",System.currentTimeMillis()).put("hostProcessMemory",memory());write(evidence,report);}
 }
 private void base(Map<String,OnnxTensor> map,List<OnnxTensor> owned,float[] latent,float[] text,float[][] residuals)throws Exception {put(map,owned,"sample",half(latent,1,4,64,64));put(map,owned,"timestep",half(new float[]{500},1));put(map,owned,"encoder_hidden_states",half(text,1,77,768));for(int i=0;i<13;i++)put(map,owned,residual(i),half(residuals[i],RESIDUALS[i]));}
 private float[][] control(LocalDrawingEngine runner,OrtSession session,float[] latent,float[] text)throws Exception {float[] hint=new float[3*512*512];for(int y=0;y<512;y++)for(int x=0;x<512;x++)if(x%64<2||y%64<2)for(int c=0;c<3;c++)hint[c*512*512+y*512+x]=1;try(OnnxTensor sample=half(latent,1,4,64,64);OnnxTensor time=half(new float[]{500},1);OnnxTensor embedding=half(text,1,77,768);OnnxTensor guide=half(hint,1,3,512,512)){Map<String,OnnxTensor> inputs=new LinkedHashMap<>();inputs.put("sample",sample);inputs.put("timestep",time);inputs.put("encoder_hidden_states",embedding);inputs.put("canny_image",guide);try(OrtSession.Result result=runner.run(session,inputs)){float[][] residuals=new float[13][];for(int i=0;i<13;i++)residuals[i]=values(result,residual(i),RESIDUALS[i]);return residuals;}}}
 private OnnxTensor half(float[] values,long...shape)throws Exception{return OnnxTensor.createTensor(environment,Fp16Conversions.convertFloatBufferToFp16Buffer(FloatBuffer.wrap(values)),shape,OnnxJavaType.FLOAT16);}
 private static void put(Map<String,OnnxTensor> map,List<OnnxTensor> owned,String name,OnnxTensor value){owned.add(value);map.put(name,value);}
 private static float[] values(OrtSession.Result result,String name,long...shape)throws Exception {OnnxValue value=result.get(name).orElseThrow(()->new IllegalStateException("Missing actual tensor "+name));assertTrue(value instanceof OnnxTensor);OnnxTensor tensor=(OnnxTensor)value;assertEquals(OnnxJavaType.FLOAT16,tensor.getInfo().type);assertArrayEquals(shape,tensor.getInfo().getShape());FloatBuffer data=tensor.getFloatBuffer();float[] values=new float[data.remaining()];data.get(values);for(float number:values)assertTrue("Finite actual tensor "+name,Float.isFinite(number));return values;}
 private static JSONObject metadata(Map<String,NodeInfo> values)throws Exception {JSONObject out=new JSONObject();for(Map.Entry<String,NodeInfo> item:values.entrySet()){assertTrue(item.getValue().getInfo() instanceof TensorInfo);TensorInfo info=(TensorInfo)item.getValue().getInfo();out.put(item.getKey(),new JSONObject().put("type",info.type.toString()).put("shape",new JSONArray(info.getShape())));}return out;}
 private static JSONObject difference(float[] a,float[] b)throws Exception {assertEquals(a.length,b.length);double sum=0,sq=0,max=0,base=0;for(int i=0;i<a.length;i++){double delta=Math.abs((double)a[i]-b[i]);sum+=delta;sq+=delta*delta;max=Math.max(max,delta);base+=(double)a[i]*a[i];}double rms=Math.sqrt(sq/a.length),baseRms=Math.sqrt(base/a.length);return new JSONObject().put("maxAbs",max).put("meanAbs",sum/a.length).put("rms",rms).put("baselineRms",baseRms).put("relativeRms",rms/Math.max(baseRms,1e-12));}
 private static JSONObject tensorFile(File directory,String name,float[] values)throws Exception {ByteBuffer bytes=ByteBuffer.allocate(values.length*4).order(ByteOrder.LITTLE_ENDIAN);for(float value:values)bytes.putFloat(value);byte[] data=bytes.array();File file=new File(directory,name);Files.write(file.toPath(),data);return new JSONObject().put("file",name).put("bytes",data.length).put("sha256",SketchDocument.sha256(data)).put("format","Little-endian FP32 conversion of actual returned FP16 noise tensor; not artwork");}
 private static String residual(int i){return i<12?"down_residual_"+i:"mid_residual";}
 private static JSONObject memory(){JSONObject out=new JSONObject();try{for(String line:Files.readAllLines(new File("/proc/self/status").toPath(),StandardCharsets.UTF_8))if(line.startsWith("VmRSS:")||line.startsWith("VmHWM:"))out.put(line.substring(0,line.indexOf(':')),line.substring(line.indexOf(':')+1).trim());out.put("scope","Host test process only; not phone evidence");}catch(Exception ignored){}return out;}
 private static void write(File file,JSONObject object)throws Exception {Files.write(file.toPath(),object.toString(2).getBytes(StandardCharsets.UTF_8));}
}
